{"meetingId": "625", "tickets": [
{"title": "Prepare mortgage liquidity source analysis", "text": "Compare bank cash, short-term bond holdings, taxable brokerage sales, and vested Cloudberry Kite Robotics shares at Velvet Acorn Custody as funding sources for Julian and Iris Nettlewhisk's remaining down payment on the $945,000 Portland townhouse, preserving at least $80,000 in post-closing emergency reserves from the $172,000 held at Teacup Comet Bank.", "priority": null, "dueDate": "2025-10-08", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "Julian asked for a mortgage liquidity source analysis comparing bank cash, short-term bond holdings, taxable brokerage sales, and vested employer shares to fund the remaining down payment while preserving the stated reserve target; the agreed follow-up is due 2025-10-08."},
{"title": "Collect underwriting asset documentation", "text": "Obtain and upload the most recent Teacup Comet Bank statement and Velvet Acorn Custody brokerage statement to the lender's portal, and provide documentation tying the $25,000 earnest money withdrawal to the source account for Julian and Iris Nettlewhisk's mortgage underwriting.", "priority": null, "dueDate": "2025-10-06", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the lender's portal shows the most recent Teacup Comet Bank statement and Velvet Acorn Custody brokerage statement have not been uploaded, and the underwriter is asking for documentation tying the earnest money withdrawal to the source account; this remains needed by 2025-10-06."},
{"title": "Review cash-flow effect of rate-lock alternatives", "text": "Review the updated loan terms from the mortgage contact for Julian and Iris Nettlewhisk, comparing the cash-flow effect of the rate-lock alternatives against the preliminary $5,850 monthly mortgage estimate and the financing contingency timeline before Julian responds.", "priority": null, "dueDate": "2025-10-10", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The mortgage contact sent updated loan terms with a rate-lock choice and financing contingency timeline, and Julian wants the cash-flow effect of the lock alternatives reviewed before he responds; the agreed review is due 2025-10-10."},
{"title": "Resolve student loan payment discrepancy", "text": "Reconcile the student loan payment discrepancy in Julian and Iris Nettlewhisk's mortgage file: the application lists Iris's payment as $640 per month while the current servicer statement shows a $410 income-driven payment, which changes the debt-to-income calculation for underwriting.", "priority": null, "dueDate": "2025-10-07", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the mortgage application lists Iris's student loan payment as $640 per month, while the current servicer statement provided by Iris shows a $410 income-driven payment, creating a different debt-to-income calculation for underwriting; resolution remains needed by 2025-10-07."},
{"title": "Reconcile stale brokerage aggregation feed", "text": "Reconcile the stale Velvet Acorn Custody aggregation feed in the planning portal so the liquidity worksheet reflects the current cash and short-term bond positions in Julian and Iris Nettlewhisk's joint taxable brokerage account available for closing.", "priority": null, "dueDate": "2025-10-06", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The Velvet Acorn Custody aggregation feed in the planning portal is showing a stale joint brokerage balance, so the liquidity worksheet is not reflecting the current cash and short-term bond positions available for closing; the agreed follow-up is due 2025-10-06."},
{"title": "Coordinate new-home insurance and liability coverage", "text": "Coordinate new-home insurance and liability coverage for Julian and Iris Nettlewhisk's Portland townhouse purchase, replacing the renters-only coverage in their current policy set to address the changed property and liability exposure.", "priority": null, "dueDate": "2025-10-15", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The townhouse purchase changes the household's property and liability exposure, and the couple has only renters coverage in place through their current policy set; the agreed new-home insurance and liability coordination is due 2025-10-15."},
{"title": "Review taxable ETF tax lots", "text": "Review the taxable ETF positions in Julian and Iris Nettlewhisk's joint brokerage account at Velvet Acorn Custody, which include both short-term gain lots and lower-gain long-term lots, to identify which holdings are most suitable if brokerage assets are used for closing cash.", "priority": null, "dueDate": "2025-10-09", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "several taxable ETF positions have both short-term gain lots and lower-gain long-term lots, affecting which holdings may be most suitable if brokerage assets are used for closing cash; the agreed tax-lot review is due 2025-10-09."}
]}
